def classify(op, kind, detail):
    if kind == "ERROR":
        if detail.startswith("TestAlreadyEvaluated:"):
            return "EVALUATED"
    if kind == "ACCEPT" and "ACCEPTED-BY-GATES" in detail:
        return "ACCEPT"
